import time
from threading import Thread

def crunch(n):
    total = 0
    for i in range(n):
        total += i * i

t0 = time.perf_counter()
threads = [Thread(target=crunch, args=(10_000_000,)) for _ in range(4)]
for t in threads:
    t.start()
for t in threads:
    t.join()
print(f"{time.perf_counter() - t0:.2f}s")  # ~= serial time: GIL serialises
